import { Group, Mesh, PlaneGeometry } from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { primitives } from '@/primitives';
import { text } from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {string} [imageUrl]
 * @property {Array<{text:string, role:string, typography?:{fontSize:number}}>} [textContent]
 * @property {Array<{name:string, params:any, trigger:string}>} [cinematicPrimitives]
 * @property {Object} [intent]
 * @property {Object} [intent.visualSpec]
 * @property {Array<{text:string, role:string, typography?:{fontSize:number}}>} [intent.visualSpec.textContent]
 */

/**
 * @typedef {Object} NodeContext
 * @property {Object} THREE
 * @property {Object} textureLoader
 * @property {Object} glbLoader
 * @property {Object} [videoLoader]
 * @property {Object} fontAtlas
 * @property {Object} primitives
 * @property {Function} emit
 * @property {string} [tier]
 */

/**
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root container
  const root = new Group();
  root.name = 'PricingCard2';

  // Geometry – a simple plane (size 1x1, can be scaled externally)
  const geometry = new PlaneGeometry(1, 1);
  // Material – basic node material with texture map
  const material = new MeshBasicNodeMaterial();
  material.color.set('#0b0b10'); // surface fallback color

  // Load texture if provided
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  const mesh = new Mesh(geometry, material);
  mesh.name = 'CardPlane';
  root.add(mesh);

  // Apply cinematic primitives if any (none for this node, but keep pattern)
  const primitiveInstances = [];
  if (config.cinematicPrimitives) {
    for (const prim of config.cinematicPrimitives) {
      const instance = ctx.primitives[prim.name](root, prim.params);
      primitiveInstances.push(instance);
    }
  }

  // Text handling – none for this node, but keep placeholder for future
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of textItems) {
    const txtObj = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 0.13,
      color: '#e8ecf2',
      align: 'center',
    });
    root.add(txtObj);
  }

  // Event handlers container (empty as no interactions defined)
  root.userData.handlers = {};

  // Cleanup routine
  root.userData.cleanup = () => {
    // Dispose primitives
    for (const inst of primitiveInstances) {
      if (inst && typeof inst.cleanup === 'function') {
        inst.cleanup();
      }
    }
    // Dispose material and geometry
    if (material.map && typeof material.map.dispose === 'function') {
      material.map.dispose();
    }
    material.dispose();
    geometry.dispose();

    // Kill any GSAP timelines that might have been created
    gsap.globalTimeline.clear();
  };

  return root;
}
